Set.Payload:
    {
    "contents": [
        {
            "parts": [
                {
                    "text": "Process refund for return {returnId} with payload {escapeJSON(request.content)}. Generate a meaningful RefundConfirmation."
                }
            ],
            "role": "user"
        }
    ],
    "generationConfig": { 
        "response_mime_type": "application/json",
        "response_schema": {
          "description": "Represents a refund confirmation.",
          "type": "object",
          "required": [
            "returnId",
            "type",
            "amount",
            "confirmationId",
            "processedAt"
          ],
          "properties": {
            "returnId": {
              "type": "string",
              "description": "The ID of the return request."
            },
            "type": {
              "type": "string",
              "enum": [
                "refund",
                "credit"
              ],
              "description": "The type of refund that was processed."
            },
            "amount": {
              "type": "number",
              "description": "The amount that was refunded or credited."
            },
            "confirmationId": {
              "type": "string",
              "description": "The unique ID of the refund transaction."
            },
            "processedAt": {
              "type": "string",
              "format": "date-time",
              "description": "The timestamp when the refund was processed."
            }
          }
        }
    }
}
